DROP TABLE IF EXISTS livres_categories, emprunts, livres, categories, membres, auteurs CASCADE;
CREATE TABLE auteurs (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nom VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE, cree_le TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE membres (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nom VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, actif BOOLEAN NOT NULL DEFAULT TRUE, inscrit_le DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE livres (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, titre VARCHAR(200) NOT NULL, auteur_id INTEGER NOT NULL REFERENCES auteurs(id), isbn VARCHAR(17) UNIQUE, annee SMALLINT CHECK (annee > 0), disponible BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE categories (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nom VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE livres_categories (livre_id INTEGER REFERENCES livres(id) ON DELETE CASCADE, categorie_id INTEGER REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY (livre_id, categorie_id));
CREATE TABLE emprunts (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, livre_id INTEGER NOT NULL REFERENCES livres(id), membre_id INTEGER NOT NULL REFERENCES membres(id), date_emprunt DATE NOT NULL DEFAULT CURRENT_DATE, date_retour DATE, CHECK (date_retour IS NULL OR date_retour >= date_emprunt));
CREATE INDEX idx_livres_auteur ON livres(auteur_id);
CREATE INDEX idx_emprunts_membre_date ON emprunts(membre_id, date_emprunt);
CREATE INDEX idx_emprunts_retour ON emprunts(date_retour);
